sql.where:
AND `LANGUAGE` = 'ko'

	 AND CODE_TYPE = #{codeType}




			AND ID LIKE CONCAT('%', #{query}, '%')


			AND LABEL LIKE CONCAT('%', #{query}, '%')




	 AND EXTENSION_CODE = #{extensionCode}


	 AND UP_ID = #{upId}

mapper.select:
SELECT CODE_TYPE, `LANGUAGE`, ID, LABEL, DETAIL, ORDERING, USE_YN,
 	UP_ID, CODE_VALUE, EXTENSION_CODE, MAPPING_CODE
FROM OP_COMMON_CODE
WHERE CODE_TYPE = #{codeType}
	AND `LANGUAGE` = 'ko' AND ID = #{id}

mapper.delete:
DELETE FROM OP_COMMON_CODE
WHERE
	CODE_TYPE = #{codeType}
	AND `LANGUAGE` = 'ko'
	AND ID = #{id}

mapper.select:
SELECT C.CODE_TYPE, C.LANGUAGE, C.ID, C.LABEL, C.DETAIL, C.ORDERING, C.USE_YN,
	 C.UP_ID, C.CODE_VALUE, C.EXTENSION_CODE, C.MAPPING_CODE
FROM OP_COMMON_CODE C
WHERE C.CODE_TYPE = #{codeType}

	 AND C.UP_ID = #{upId}



		AND C.USE_YN = #{useYn}


		AND C.USE_YN = 'Y'




		AND C.`LANGUAGE` = #{language}


		AND C.`LANGUAGE` = 'ko'


ORDER BY C.ORDERING
